require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();verify_csrf();$id=(int)($_POST['application_id']??0);$status=$_POST['status']??'';$feedback=trim($_POST['reviewer_feedback']??'');if(!$id||!in_array($status,['submitted','under_review','shortlisted','unsuccessful','accepted'],true)||mb_strlen($feedback)>4000)json_response(['ok'=>false,'message'=>'Enter a valid review.'],422);
$reviewer=(int)user()['id'];$s=$con->prepare('UPDATE job_applications SET status=?,reviewer_feedback=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?');$s->bind_param('ssii',$status,$feedback,$reviewer,$id);$s->execute();$s=$con->prepare('SELECT a.user_id,j.title FROM job_applications a JOIN job_opportunities j ON j.id=a.job_id WHERE a.id=?');$s->bind_param('i',$id);$s->execute();$a=$s->get_result()->fetch_assoc();if(!$a)json_response(['ok'=>false,'message'=>'Application not found.'],404);notify_user($con,$a['user_id'],'job_application','Your application for '.$a['title'].' was updated to '.str_replace('_',' ',$status).'.');admin_log($con,'review','job_application',$id,'Status: '.$status);json_response(['ok'=>true,'message'=>'Application review saved.']);
